// Ported from the Node app's Sequelize model JobOpening (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class JobOpeningConfiguration : IEntityTypeConfiguration<JobOpening>
{
    public void Configure(EntityTypeBuilder<JobOpening> builder)
    {
        builder.ToTable("job_openings", t =>
        {
            t.HasCheckConstraint("CK_job_openings_status", "[status] IN (N'open', N'closed')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Title).HasColumnName("title").HasColumnType("nvarchar(120)").HasMaxLength(120).IsRequired();
        builder.Property(e => e.DepartmentId).HasColumnName("department_id");
        builder.Property(e => e.Vacancies).HasColumnName("vacancies");
        builder.Property(e => e.Description).HasColumnName("description").HasColumnType("nvarchar(500)").HasMaxLength(500);
        builder.Property(e => e.ClosingDate).HasColumnName("closing_date").HasColumnType("date");
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'open'");
        builder.HasOne(e => e.Department).WithMany(p => p.JobOpenings).HasForeignKey(e => e.DepartmentId).OnDelete(DeleteBehavior.NoAction);
    }
}
